using System;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
namespace MP1SkinStudio
{
    public static partial class SelfTests
    {
        static SkinProject MarkFixture(string root,string name,string extra="")
        {return AuditFixture(root,name,"<control><type>checkmark</type><id>20</id><width>500</width><height>60</height><markWidth>20</markWidth><markHeight>20</markHeight>"+extra+"</control>");}
        static void RunCheckmarkTests(string root)
        {
            Test("Checkmark selection resolves true false and explicit samples without guessing",()=>
            {var p=MarkFixture(root,"mark-selection");var c=p.Controls[0];Check(CheckmarkPresentation.Selected(c,new PreviewState(p))==false,"Default checkmark should be unselected.");p.Edit(c,Set("selected","#selection"),"Runtime selection");var s=new PreviewState(p);Check(CheckmarkPresentation.Selected(p.Controls[0],s)==null,"Unknown selection was guessed.");p.Editor.Preview.Values["#selection"]="True";Check(CheckmarkPresentation.Selected(p.Controls[0],new PreviewState(p))==true,"True sample failed.");p.Editor.Preview.Values["#selection"]="yes";Check(CheckmarkPresentation.Selected(p.Controls[0],new PreviewState(p))==null,"Native bool parsing was broadened to yes.");p.Editor.Preview.Values["#selection"]="False";Check(CheckmarkPresentation.Selected(p.Controls[0],new PreviewState(p))==false,"False sample failed.");});
            Test("Checkmark dimensions preserve XML spelling and reset inherited aliases",()=>
            {var p=AuditFixture(root,"mark-case","<control><type>checkmark</type><id>20</id><MarkWidth>25</MarkWidth><MarkHeight>30</MarkHeight></control>");Write(p.Root,"references.xml","<window><control><type>checkmark</type><markWidth>10</markWidth><markHeight>12</markHeight></control></window>");p=new SkinProject(p.Root);p.OpenPage("main.xml");int w,h;Check(CheckmarkPresentation.Layout(p.Controls[0],out w,out h)&&w==25&&h==30,"Case alias precedence failed.");string before=p.Controls[0].Source.Text;p.Edit(p.Controls[0],Set("markWidth","35"),"Mark width");Check(p.Controls[0].Source.Text.Contains("<MarkWidth>35</MarkWidth>")&&!p.Controls[0].Source.Text.Contains("<markWidth>"),"Editing duplicated or renamed source XML.");p.ResetProperty(new[]{p.Controls[0]},"markWidth",true);Check(p.Controls[0].Get("markWidth")=="10","Reset did not restore inherited dimension.");p.UndoChange();p.UndoChange();Check(p.Controls[0].Source.Text==before,"Dimension undo was not exact.");});
            Test("Ambiguous checkmark dimension aliases reject edits and reset atomically",()=>
            {var p=MarkFixture(root,"mark-duplicate","<MarkWidth>30</MarkWidth>");string xml=p.Controls[0].Source.Text;Reject(()=>p.Edit(p.Controls[0],Set("markWidth","40"),"Duplicate mark width"));Reject(()=>p.ResetProperty(new[]{p.Controls[0]},"markWidth",true));Check(p.Controls[0].Source.Text==xml&&!p.Dirty,"Ambiguous dimension edits mutated source.");});
            Test("Checkmark label alignment positions the mark before or after measured text",()=>
            {var p=MarkFixture(root,"mark-align","<align>right</align>");var c=p.Controls[0];var bounds=new RectangleF(50,100,500,60);Check(CheckmarkPresentation.MarkArea(c,bounds,120,20,30)==new RectangleF(50,100,20,30),"Right label alignment moved mark.");p.Edit(c,Set("align","left"),"Text before mark");Check(CheckmarkPresentation.MarkArea(p.Controls[0],bounds,120,20,30)==new RectangleF(175,100,20,30),"Text-first mark position failed.");});
            Test("Checkmark invalid or dynamic dimensions remain unverified with diagnostics",()=>
            {foreach(string value in new[]{"NaN","-1","8193","#missing"}){var p=MarkFixture(root,"mark-invalid-"+Guid.NewGuid().ToString("N"));p.Edit(p.Controls[0],Set("markWidth",value),"Unsupported dimension");int w,h;Check(!CheckmarkPresentation.Layout(p.Controls[0],out w,out h)&&PreviewProblems.Run(p,new PreviewState(p)).Issues.Any(i=>i.Code=="PREVIEW_CHECKMARK"&&i.Information),"Invalid mark layout was accepted.");}});
            Test("Mixed button checkmark stacks navigate without changing selection or XML",()=>
            {var p=AuditFixture(root,"mark-navigation","<control><type>group</type><layout>StackLayout(10)</layout>"+NestedButton(10)+"<control><type>checkmark</type><id>20</id><width>100</width><height>50</height><selected>#unknown</selected></control>"+NestedButton(30)+"</control>");var s=new PreviewState(p){FocusId=10};string xml=ProjectFile.XmlSignature(p);GridMove(p,s,"ondown",20);GridMove(p,s,"ondown",30);GridMove(p,s,"onup",20);GridMove(p,s,"onup",10);Check(ProjectFile.XmlSignature(p)==xml&&!p.Dirty&&CheckmarkPresentation.Selected(p.Controls.First(c=>c.Get("id")=="20"),s)==null,"Navigation toggled selection or XML.");});
            Test("Checkmark navigation preserves collection and duplicate ID guards",()=>
            {foreach(string extra in new[]{"<control><type>listcontrol</type><id>30</id><width>100</width><height>50</height></control>","<control><type>checkmark</type><id>020</id><width>100</width><height>50</height></control>"}){var p=AuditFixture(root,"mark-nav-guard-"+Guid.NewGuid().ToString("N"),"<control><type>button</type><id>10</id><width>100</width><height>50</height></control><control><type>checkmark</type><id>20</id><posX>200</posX><width>100</width><height>50</height></control>"+extra);var s=new PreviewState(p){FocusId=10};Reject(()=>p.PreviewNavigationTarget(s,"onright"));Check(s.FocusId==10&&!p.Dirty,"Guard leaked focus or XML.");}});
            Test("Production checkmark rendering uses selection textures independently of focus",()=>
            {var p=MarkFixture(root,"mark-pixels","<selected>true</selected><textureCheckmark>on.png</textureCheckmark><textureCheckmarkNoFocus>off.png</textureCheckmarkNoFocus>");Directory.CreateDirectory(Path.Combine(p.Root,"Media"));using(var asset=new Bitmap(2,2))using(var paint=Graphics.FromImage(asset)){paint.Clear(Color.Red);asset.Save(Path.Combine(p.Root,"Media/on.png"));paint.Clear(Color.Blue);asset.Save(Path.Combine(p.Root,"Media/off.png"));}using(var canvas=new SkinCanvas{Project=p,State=new PreviewState(p)})using(var output=new Bitmap(100,100))using(var g=Graphics.FromImage(output)){canvas.CheckmarkForTest(g,p.Controls[0],new RectangleF(0,0,100,60),false);Check(output.GetPixel(10,10).R>240,"Selected mark texture missing.");g.Clear(Color.Transparent);canvas.CheckmarkForTest(g,p.Controls[0],new RectangleF(0,0,100,60),true);Check(output.GetPixel(10,10).R>240,"Focus changed selected texture.");p.Edit(p.Controls[0],Set("selected","false"),"Unselect mark");canvas.State=new PreviewState(p);canvas.CheckmarkForTest(g,p.Controls[0],new RectangleF(0,0,100,60),true);Check(output.GetPixel(10,10).B>240,"Unselected texture missing.");p.Edit(p.Controls[0],Set("selected","#unknown"),"Unverified mark");canvas.State=new PreviewState(p);g.Clear(Color.Transparent);canvas.CheckmarkForTest(g,p.Controls[0],new RectangleF(0,0,100,60),true);Check(output.GetPixel(10,10).A==0,"Unknown selection drew a guessed mark.");}});
            Test("Checkmark property edits persist export and restore exact undo redo",()=>
            {var p=MarkFixture(root,"mark-roundtrip","<selected>false</selected>");byte[] original=File.ReadAllBytes(p.Controls[0].Source.Path);string before=p.Controls[0].Source.Text;p.Edit(p.Controls[0],new System.Collections.Generic.Dictionary<string,string>{{"selected","true"},{"markWidth","35"},{"disabledcolor","ffaaaaaa"}},"Edit checkmark");string after=p.Controls[0].Source.Text,file=Path.Combine(root,"checkmark.mp1skinproj"),zip=Path.Combine(root,"checkmark.zip");ProjectFile.Save(p,file);var q=ProjectFile.Load(file);Check(CheckmarkPresentation.Selected(q.Controls[0],new PreviewState(q))==true&&q.Controls[0].Get("markWidth")=="35","Checkmark edits did not reopen.");q.Export(zip);using(var archive=ZipFile.OpenRead(zip))using(var reader=new StreamReader(archive.GetEntry("main.xml").Open()))Check(reader.ReadToEnd()==after,"Checkmark export changed XML.");q.UndoChange();Check(q.Controls[0].Source.Text==before,"Restored mark undo failed.");q.RedoChange();Check(q.Controls[0].Source.Text==after&&File.ReadAllBytes(q.Controls[0].Source.Path).SequenceEqual(original),"Mark redo changed disk originals.");});
        }
    }
}
